/** Extract the reviewed Thai segmentation table without shipping authoring rows. */
const fs = require('node:fs');
const path = require('node:path');
const { ROOT, loadSeeds } = require('./load-data.cjs');
const { window } = loadSeeds();
const output = path.join(ROOT, 'dist/data-th-tokens.js');
fs.writeFileSync(
  output,
  '// Generated by scripts/build-thai-tokens.cjs from scripts/source/data-th-glossary.js.\n' +
    '// Token boundaries for Thai sentences; readings/meanings are separate dictionaries.\n' +
    'window.THAI_CARD_TOKENS = ' +
    JSON.stringify(window.THAI_CARD_TOKENS) +
    ';\n',
);
console.log(JSON.stringify({ tokens: Object.keys(window.THAI_CARD_TOKENS).length, output }));
